import{_ as o,C as r,o as n,c as i,j as s,a,E as l,a4 as p}from"./chunks/framework.fFCcJnNq.js";const k=JSON.parse('{"title":"How It Works","description":"","frontmatter":{"title":"How It Works","aside":false,"pageClass":"pp-wide"},"headers":[],"relativePath":"how-it-works.md","filePath":"how-it-works.md","lastUpdated":null}'),c={name:"how-it-works.md"},d={class:"pp-hiw-page"};function m(h,e,f,u,w,A){const t=r("HowItWorks",!0);return n(),i("div",null,[s("div",d,[e[0]||(e[0]=s("p",{class:"pp-eyebrow"},"How it works",-1)),e[1]||(e[1]=s("h1",null,"All pairs, from one sparse factorization.",-1)),e[2]||(e[2]=s("div",{class:"pp-hiw-intro"},[s("p",null,[a("An algebraic path problem asks for the "),s("em",null,"star"),a(" of a graph's weighted adjacency matrix, "),s("span",{style:{"white-space":"nowrap"}},"A* = I ⊕ A ⊕ A² ⊕ ⋯"),a(", over a semiring. With ⊕ = min and ⊗ = +, A*[i, j] is the shortest distance from i to j. Other semirings ask other questions with the same formula: widest paths (max, min), bottleneck paths (min, max), reachability (or, and), sums over all walks (+, ×).")]),s("p",null,"Floyd–Warshall computes A* with the loops of Gaussian elimination: n³ updates on a dense matrix. PATHPACK.jl uses a sparse direct method instead. It orders the vertices to limit fill, factorizes A into sparse triangular factors L and U over the semiring, and then solves against the identity, row by row, to get A*."),s("p",null,"The steps below run on a small street grid. Every order, factor and distance in them is computed in your browser for the graph shown.")],-1)),l(t),e[3]||(e[3]=p(`<div class="pp-hiw-after"><h2>In code</h2><p>One call does all of it. To answer many single-source questions, keep the factorization: each query is two triangular solves.</p><pre class="pp-codeblock"><code><span class="k">using</span> PATHPACK, SparseArrays, LinearAlgebra
<span class="k">using</span> PATHPACK.CPU: MinPlus, mstar, mlu
D = <span class="f">mstar</span>(<span class="s">MinPlus</span>(), A)                   <span class="c"># all of A*: order, factorize, solve</span>
F = <span class="f">mlu</span>(<span class="s">MinPlus</span>(), A)                     <span class="c"># or keep the factors</span>
B = <span class="f">fill</span>(Inf, 1, size(A, 1)); B[s] = 0.0  <span class="c"># the unit row vector at s</span>
<span class="f">rmul!</span>(B, F)                               <span class="c"># row s of A*: the distances from s</span></code></pre><p>The keyword <code>alg</code> of <code>mlu</code> and <code>mstar</code> picks the ordering, for example <code>METIS()</code> (nested dissection) from CliqueTrees.jl. On NVIDIA GPUs, <code>apsp_gpu(A)</code> runs the same method: CPU threads factorize the many small parts, the GPU the large separator blocks, and the rows of A* are split across one GPU or several.</p></div>`,1))])])}const _=o(c,[["render",m]]);export{k as __pageData,_ as default};
